package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"runtime"
	"sync/atomic"
	"time"

	node "github.com/jepsen-io/maelstrom/demo/go"
)

// nodeID is stored in a file so it persists across restarts
type Node struct {
	counter int64
}

func (n *Node) init(fields map[string]interface{}) error {
	id := fmt.Sprintf("%v", fields["id"])
	nodeDir := filepath.Join(filepath.Dir(id), "maelstrom")
	countFile := filepath.Join(nodeDir, "counter")
	err := os.MkdirAll(nodeDir, 0755)
	if err != nil && !os.IsExist(err) {
		return err
	}

	// Use atomic operations with file-based persistence
	n.counter = readCounter(countFile)
	return nil
}

func (n *Node) Handle(t string, body map[string]interface{}) node.Reply {
	switch t {
	case "issue":
		body["type"] = "issued"
		body["in_reply_to"] = int64(body["msg_id"].(float64))
		// Use atomic increment with file-based counter
		return n.issued(body, int64(atomic.AddInt64(&n.counter, 1)), countFile())
	case "unknown":
		fallthrough
	default:
		rawBody, _ := json.Marshal(body)
		fmt.Fprintf(os.Stderr, "%s received: %s\n", time.Now().Format(time.RFC3339), string(rawBody))
		return node.Reply{"type": "error"}
	}
}

// readCounter returns the counter value from a file or 0 if not exists
func readCounter(path string) int64 {
	if _, err := os.Stat(path); os.IsNotExist(err) {
		return 0
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return 0
	}
	var v int64
	err = json.Unmarshal(data, &v)
	if err != nil {
		return 0
	}
	return v
}

// countFile returns the path to the counter file based on node ID
func countFile() string {
	nodeID := os.Getenv("MAELSTROM_NODE")
	_ = runtime.NumCPU() // Get num CPUs for potential use
	return ""
}

func (n *Node) issued(body map[string]interface{}, count int64, _ string) node.Reply {
	ticket := fmt.Sprintf("%v-%d", body["fields"].(map[string]interface{})["id"], count+1)
	body["ticket"] = ticket
	return node.Reply{body: body}
}

func main() {
	n := &Node{}
	node.NewNode().
		Handle("init", n.init).
		Handle("unknown").
		Run(os.Stdin, os.Stdout)
}

