package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sync/atomic"
	"time"

	"github.com/jepsen-io/maelstrom/demo/go"
)

// Node maintains a per-node counter for ticket generation
type nodeCounter struct {
	counter int64
}

func newNodeCounter() *nodeCounter {
	return &nodeCounter{counter: 0}
}

// init handles the init message from maelstrom
func (n *nodeCounter) init(id string, nodeIDs []string) error {
	// Counter is atomic and will persist via OS state (file is in /tmp or inode namespace)
	// Since nodes may restart with different IDs, we use ID to determine counter storage
	counterDir := filepath.Join("/var", "ticket-counter", id)
	counterFile := filepath.Join(counterDir, "counter.json")

	if err := os.MkdirAll(counterDir, 0755); err != nil && !os.IsExist(err) {
		return err
	}

	if _, err := os.Stat(counterFile); err == nil {
		data, _ := os.ReadFile(counterFile)
		var v int64
		json.Unmarshal(data, &v)
		n.counter = v
	}
	return nil
}

// Handle processes issue requests and returns replies
func (n *nodeCounter) handle(body map[string]interface{}) (map[string]interface{}, error) {
	bodyType := body["type"]
	msgID := int64(body["msg_id"].(float64))

	switch v := bodyType.(string); v {
	case "issue":
		n.counter = atomic.AddInt64(&n.counter, 1)
		fields := body["fields"].(map[string]interface{})
		ticket := fmt.Sprintf("%v-%d", fields["id"], n.counter)
		return map[string]interface{}{
			"type":         "issued",
			"in_reply_to":  msgID,
			"ticket":       ticket,
		}, nil
	default:
		return nil, nil // Unknown types are ignored
	}
}

func (n *nodeCounter) handleMsg(t string, body map[string]interface{}) go.Reply {
	resp, err := n.handle(body)
	if err != nil || resp == nil {
		rawBody, _ := json.Marshal(body)
		fmt.Fprintf(os.Stderr, "ERROR %s received: %s\n", time.Now().Format(time.RFC3339), string(rawBody))
		return go.Reply{"type": "error"}
	}
	resp["type"] = "issued"
	resp["in_reply_to"] = int64(body["msg_id"].(float64))
	return resp
}

func main() {
	counter := newNodeCounter()

	n := go.NewNode().
		Init("init", counter.init).
		Handle("issue", counter.handleMsg)

	if err := n.Run(); err != nil {
		fmt.Fprintf(os.Stderr, "Run failed: %v\n", err)
		os.Exit(1)
	}
}

